/**
 * TECH-03 progress metrics (docs/architecture/migration-tailwind.md, « Critère pour déclarer TECH-03 complet »).
 *
 * Usage: node scripts/tailwind-metrics.ts [--ref <git ref of the legacy sheets>] [--json] [--strict]
 * - criterion 1: single CSS entry point, every project sheet imported in a layer;
 * - criterion 2: share of the original declarations (legacy sheets, without @font-face and @keyframes) no longer written in
 *   CSS, i.e. expressed as utilities in the JSX (or removed as redundant), and number of utilities generated by Tailwind;
 * - criterion 3: size of the remaining project CSS (comments and indentation removed), by file;
 * - criterion 4: raw `[data-theme=dark]` and width media queries outside globals.css;
 * - criterion 5: hex literals outside @theme (all / outside gradients, url() and SVG data);
 * - criterion 6: remaining rules that only carry layout, spacing or typography (candidates for utilities).
 * `--strict` exits with 1 when a criterion is not met.
 */
import {execFileSync} from 'node:child_process';
import {existsSync,readFileSync,readdirSync} from 'node:fs';
import {join} from 'node:path';
import postcss,{type AtRule,type Container,type Declaration,type Rule} from 'postcss';
import tailwind from '@tailwindcss/postcss';

const root=process.cwd(),args=process.argv.slice(2);
const ref=args.includes('--ref')?args[args.indexOf('--ref')+1]:'3049ba3';
const legacy=['src/style.css','src/jungle.css','src/auth.css','src/expeditions.css','src/woodland.css','src/race-tracks.css','src/lobby-compact.css','src/play-experience.css','src/results.css','src/results-reference.css','app/globals.css'];
const stylesDir=join(root,'src/styles');
const sheets=readdirSync(stylesDir).filter(name=>name.endsWith('.css')).sort();

/** Declarations outside @font-face and @keyframes. */
function declarations(css:string){
 const found:Declaration[]=[];
 postcss.parse(css).walkDecls(decl=>{let parent:Container|undefined=decl.parent as Container;while(parent){if(parent.type==='atrule'&&['font-face','keyframes'].includes((parent as AtRule).name))return;parent=parent.parent as Container|undefined}found.push(decl)});
 return found;
}
const minified=(css:string)=>css.replace(/\/\*[\s\S]*?\*\//g,'').replace(/\n\s*/g,'').trim();

// Criterion 1.
const layout=readFileSync(join(root,'app/layout.tsx'),'utf8'),globals=readFileSync(join(root,'app/globals.css'),'utf8');
const layoutImports=[...layout.matchAll(/^import\s+['"]([^'"]+\.css)['"]/gm)].map(match=>match[1]);
const imports=[...globals.matchAll(/@import\s+["']([^"']+)["']([^;]*);/g)].map(match=>({path:match[1],layered:/layer\(/.test(match[2])}));
const unlayered=imports.filter(entry=>!entry.layered&&!entry.path.endsWith('fonts.css')).map(entry=>entry.path);
const notImported=sheets.filter(name=>!imports.some(entry=>entry.path.endsWith('/styles/'+name)));
const strayCss=execFileSync('git',['ls-files','--cached','--others','--exclude-standard','*.css'],{encoding:'utf8'}).split('\n').filter(path=>path&&existsSync(join(root,path))&&!path.startsWith('src/styles/')&&!['app/globals.css','src/fonts.css'].includes(path));
const entryOk=layoutImports.length===1&&layoutImports[0]==='./globals.css'&&!unlayered.length&&!notImported.length&&!strayCss.length;

// Criterion 2.
let original=0;
for(const path of legacy){try{original+=declarations(execFileSync('git',['show',`${ref}:${path}`],{encoding:'utf8',stdio:['ignore','pipe','ignore']})).length}catch{/* sheet absent at that ref */}}
const remainingByFile=Object.fromEntries(sheets.map(name=>{const css=readFileSync(join(stylesDir,name),'utf8');return [name,{declarations:declarations(css).length,bytes:Buffer.byteLength(minified(css))}]}));
const remaining=Object.values(remainingByFile).reduce((sum,file)=>sum+file.declarations,0);
const compiled=(await postcss([tailwind({base:root,optimize:false})]).process(globals,{from:join(root,'app/globals.css')})).css;
let utilities=0;
postcss.parse(compiled).walkAtRules('layer',layer=>{if(layer.params==='utilities')layer.walkRules(rule=>{if(!rule.selector.startsWith(':'))utilities++})});
const migratedShare=original?(original-remaining)/original:0;

// Criteria 3 to 6.
const bytes=Object.values(remainingByFile).reduce((sum,file)=>sum+file.bytes,0);
let rawDark=0,rawMedia=0,hex=0,hexOutsideDecor=0,layoutOnly=0;
const utilityProperty=/^(display|position|inset|top|right|bottom|left|z-index|width|height|min-width|min-height|max-width|max-height|margin.*|padding.*|gap|row-gap|column-gap|flex.*|grid.*|align-.*|justify-.*|place-.*|order|font-size|font-weight|font-family|line-height|letter-spacing|text-align|white-space|text-transform|overflow.*|box-sizing|vertical-align)$/;
for(const name of sheets){
 const css=readFileSync(join(stylesDir,name),'utf8'),tree=postcss.parse(css);
 tree.walkRules(rule=>{if(/\[data-theme=["']?dark/.test(rule.selector))rawDark++});
 tree.walkAtRules('media',media=>{if(/(max|min)-width/.test(media.params))rawMedia++});
 tree.walkDecls(decl=>{const count=(decl.value.match(/#[0-9a-fA-F]{3,8}\b/g)||[]).length;hex+=count;if(!/gradient|url\(|data:/.test(decl.value))hexOutsideDecor+=count});
 tree.walkRules((rule:Rule)=>{if(rule.parent?.type==='atrule'&&(rule.parent as AtRule).name==='keyframes')return;const decls=rule.nodes.filter((node):node is Declaration=>node.type==='decl');if(decls.length&&decls.every(decl=>utilityProperty.test(decl.prop)&&!decl.important)&&!/:has\(|::?before|::?after|nth-|[~+]/.test(rule.selector))layoutOnly++});
}

const result={
 entryPoint:{ok:entryOk,layoutCssImports:layoutImports,unlayeredImports:unlayered,sheetsNotImported:notImported,cssOutsideStyles:strayCss},
 declarations:{original,remaining,migratedOrRemoved:original-remaining,share:Number((migratedShare*100).toFixed(1)),target:70},
 utilitiesGenerated:utilities,
 remainingCss:{bytes,kilobytes:Number((bytes/1024).toFixed(1)),targetKilobytes:50,byFile:remainingByFile},
 rawDarkSelectors:rawDark,rawWidthMedia:rawMedia,hexLiterals:{all:hex,outsideGradientsAndUrls:hexOutsideDecor},layoutOnlyRules:layoutOnly,
};
if(args.includes('--json'))console.log(JSON.stringify(result,null,1));
else{
 const line=(label:string,value:string,ok?:boolean)=>console.log(`${ok===undefined?' ':ok?'✓':'✗'} ${label.padEnd(58)} ${value}`);
 console.log(`TECH-03 — Tailwind metrics (legacy sheets read at ${ref})`);
 line('1. Single CSS entry point, every project sheet layered',entryOk?'yes':JSON.stringify(result.entryPoint),entryOk);
 line('2. Original declarations no longer in CSS (≥ 70 %)',`${result.declarations.share} % (${original-remaining} / ${original}; ${remaining} remain)`,result.declarations.share>=70);
 line('   Utilities generated by Tailwind',String(utilities));
 line('3. Remaining project CSS (≤ ~50 KB)',`${result.remainingCss.kilobytes} KB`,result.remainingCss.kilobytes<=50);
 for(const [name,file] of Object.entries(remainingByFile))line(`     ${name}`,`${(file.bytes/1024).toFixed(1)} KB, ${file.declarations} declarations`);
 line('4. Raw [data-theme=dark] / width @media outside globals.css',`${rawDark} / ${rawMedia}`,rawDark===0&&rawMedia===0);
 line('5. Hex literals outside @theme (all / outside gradients, url)',`${hex} / ${hexOutsideDecor}`,hexOutsideDecor===0);
 line('6. Rules carrying only layout/spacing/typography',String(layoutOnly),layoutOnly===0);
}
const strictFailure=!entryOk||migratedShare<.7||bytes/1024>50||rawDark>0||rawMedia>0||hexOutsideDecor>0||layoutOnly>0;
if(args.includes('--strict')&&strictFailure)process.exit(1);
